/**
 * leaflet.heat tidak menyertakan tipe dan tidak punya paket @types.
 *
 * Plugin ini bekerja dengan menambahkan L.heatLayer ke objek Leaflet global
 * sebagai efek samping impor — karena itu deklarasinya kosong: yang dibutuhkan
 * hanya izin untuk mengimpornya.
 */
declare module 'leaflet.heat';
